"use client";

import { useEffect, useRef, useState } from "react";
import type { TerminologyStore, UnifiedTerm, GlossaryTerm } from "@/lib/types";
import { authFetch } from "@/lib/clientAuth";

const inputCls =
  "w-full rounded border border-gray-200 px-2 py-1.5 text-sm focus:border-brand focus:outline-none";

const EMPTY_UNIFIED: UnifiedTerm = { category: "", zh: "", en: "", fr: "", source: "" };
const EMPTY_GLOSSARY: GlossaryTerm = {
  abbr: "",
  zhFull: "",
  enFull: "",
  explanation: "",
  scenario: "",
};

type SubTab = "unified" | "glossary";

interface Props {
  // 紧凑模式:用于前台主面板,默认表格在 admin 用
  compact?: boolean;
}

export default function TerminologyManager({ compact = false }: Props) {
  const [store, setStore] = useState<TerminologyStore | null>(null);
  const [sub, setSub] = useState<SubTab>("unified");
  const [q, setQ] = useState("");
  const [saving, setSaving] = useState(false);
  const [importing, setImporting] = useState(false);
  const [msg, setMsg] = useState("");
  const fileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    fetch("/api/terminology")
      .then((r) => (r.ok ? r.json() : { unified: [], glossary: [] }))
      .then((d) =>
        setStore({
          unified: Array.isArray(d?.unified) ? d.unified : [],
          glossary: Array.isArray(d?.glossary) ? d.glossary : [],
        })
      )
      .catch(() => setStore({ unified: [], glossary: [] }));
  }, []);

  function updateUnified(idx: number, patch: Partial<UnifiedTerm>) {
    setStore((p) =>
      p
        ? { ...p, unified: p.unified.map((r, i) => (i === idx ? { ...r, ...patch } : r)) }
        : p
    );
  }
  function updateGlossary(idx: number, patch: Partial<GlossaryTerm>) {
    setStore((p) =>
      p
        ? { ...p, glossary: p.glossary.map((r, i) => (i === idx ? { ...r, ...patch } : r)) }
        : p
    );
  }

  async function onImport(file: File) {
    setImporting(true);
    setMsg(`正在解析 ${file.name} …`);
    try {
      const form = new FormData();
      form.append("file", file);
      const res = await authFetch("/api/terminology/import", {
        method: "POST",
        body: form,
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) {
        setMsg(`导入失败:${data.error || res.status}`);
        return;
      }
      const addU: UnifiedTerm[] = Array.isArray(data.unified) ? data.unified : [];
      const addG: GlossaryTerm[] = Array.isArray(data.glossary) ? data.glossary : [];
      setStore((p) => ({
        unified: [...(p?.unified ?? []), ...addU],
        glossary: [...(p?.glossary ?? []), ...addG],
      }));
      setMsg(
