// 从上传文档总结一种文案风格:只提炼文档体现出的写作风格特征,不杜撰。
// 返回 { name, essence, group },供运营在风格库行内核对后保存。
export async function extractStyleFromDoc(
  docText: string
): Promise<{ name: string; essence: string; group: string }> {
  const client = getClient();
  const model = modelForMode("normal");
  const isKimi = model.startsWith("kimi-k2");

  const system = [
    "你是文案风格分析助手。阅读用户提供的文档,提炼它体现出的『写作风格』,产出一条可复用的风格条目。",
    "规则:",
    "1. 只描述风格特征(句式、节奏、语气、修辞、用词偏好等),不要复述文档内容,不要杜撰文档没有体现的特征。",
    "2. name:6 字以内的风格名;essence:一句话精髓(40 字以内);group:风格所属大类(如『经典广告手艺』『文学修辞味』『语域情绪』,可自拟)。",
    "3. 只返回一个 JSON 对象:{\"name\":\"\",\"essence\":\"\",\"group\":\"\"},不要任何额外文字或 markdown。",
  ].join("\n");

  const params: Record<string, unknown> = {
    model,
    max_tokens: 600,
    temperature: 0.6,
    response_format: { type: "json_object" },
    messages: [
      { role: "system", content: system },
      { role: "user", content: docText.slice(0, 12000) },
    ],
  };
  if (isKimi) params.thinking = { type: "disabled" };

  const res = await client.chat.completions.create(
    params as unknown as Parameters<typeof client.chat.completions.create>[0]
  );
  const content =
    "choices" in res ? res.choices?.[0]?.message?.content ?? "" : "";
  const parsed = JSON.parse(content) as Partial<{
    name: string;
    essence: string;
    group: string;
  }>;
  return {
    name: typeof parsed.name === "string" ? parsed.name : "",
    essence: typeof parsed.essence === "string" ? parsed.essence : "",
    group: typeof parsed.group === "string" && parsed.group ? parsed.group : "未分组",
  };
}

