import { NextRequest, NextResponse } from "next/server";
import { extractStyleFromDoc } from "@/lib/llm";
import { checkAuth } from "@/lib/auth";

export const runtime = "nodejs";
export const maxDuration = 120;

// 上传文档的纯文本 → 模型提炼一条风格条目(name/essence/group),返回草稿供前端回填
export async function POST(req: NextRequest) {
  const unauthorized = checkAuth(req);
  if (unauthorized) return unauthorized;

  let body: { text?: string };
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "请求体不是合法 JSON" }, { status: 400 });
  }

  const text = (body.text ?? "").toString().trim();
  if (!text) {
    return NextResponse.json({ error: "缺少文档文本" }, { status: 400 });
  }

  try {
    const draft = await extractStyleFromDoc(text);
    return NextResponse.json(draft);
  } catch (err) {
    const message = err instanceof Error ? err.message : "解析失败,请重试";
    return NextResponse.json({ error: message }, { status: 502 });
  }
}

