const XLSX = require("xlsx");
const fs = require("fs");
function cell(r, i) { if (i < 0) return ""; const v = r[i]; return v == null ? "" : String(v).trim(); }
function findCol(h, m) { return h.findIndex((x) => m((x ?? "").toString().trim())); }
function rows(s) { return XLSX.utils.sheet_to_json(s, { header: 1, blankrows: false, defval: "" }); }
function parseUnified(rs) {
  if (rs.length < 2) return null;
  const h = rs[0].map((x) => (x ?? "").toString().trim());
  const zh = findCol(h, (x) => x === "ZH" || x.includes("中文"));
  const en = findCol(h, (x) => x === "EN" || x.includes("英"));
  const fr = findCol(h, (x) => x === "FR" || x.includes("法"));
  if (zh < 0 || (en < 0 && fr < 0)) return null;
  const cat = findCol(h, (x) => x.includes("分类") || x.includes("类别"));
  const src = findCol(h, (x) => x.includes("来源"));
  const out = [];
  for (let i = 1; i < rs.length; i++) { const r = rs[i]; const z = cell(r, zh), e = cell(r, en), f = cell(r, fr); if (!z && !e && !f) continue; out.push({ category: cell(r, cat), zh: z, en: e, fr: f, source: cell(r, src) || undefined }); }
  return out.length ? out : null;
}
function parseGlossary(rs) {
  if (rs.length < 2) return null;
  const h = rs[0].map((x) => (x ?? "").toString().trim());
