function asString(x: unknown): string {
  return typeof x === "string" ? x : "";
}

export function validateTerminology(data: unknown): {
  ok: boolean;
  error?: string;
  value?: TerminologyStore;
} {
  if (!data || typeof data !== "object")
    return { ok: false, error: "专有术语库必须是对象" };
  const d = data as Record<string, unknown>;
  if (!Array.isArray(d.unified))
    return { ok: false, error: "unified 必须是数组" };
  if (!Array.isArray(d.glossary))
    return { ok: false, error: "glossary 必须是数组" };

  const unified: UnifiedTerm[] = (d.unified as unknown[]).map((r) => {
    const o = (r ?? {}) as Record<string, unknown>;
    return {
      category: asString(o.category),
      zh: asString(o.zh),
      en: asString(o.en),
      fr: asString(o.fr),
      source: asString(o.source) || undefined,
    };
  });
  const glossary: GlossaryTerm[] = (d.glossary as unknown[]).map((r) => {
    const o = (r ?? {}) as Record<string, unknown>;
    return {
      abbr: asString(o.abbr),
      zhFull: asString(o.zhFull),
      enFull: asString(o.enFull),
      explanation: asString(o.explanation),
      scenario: asString(o.scenario),
    };
  });

  return { ok: true, value: { unified, glossary } };
}

export async function saveTerminology(
  store: TerminologyStore,
  _userId?: string
): Promise<void> {
  await backupAndWrite(TERM_PATH, "terminology", store);
