import { NextRequest, NextResponse } from "next/server";
import {
  getTerminology,
  saveTerminology,
  validateTerminology,
} from "@/lib/store";
import { checkAuth } from "@/lib/auth";

export const runtime = "nodejs";

export async function GET() {
  try {
    const terms = await getTerminology();
    return NextResponse.json(terms, {
      headers: { "Cache-Control": "no-store" },
    });
  } catch {
    return NextResponse.json({ error: "读取专有术语库失败" }, { status: 500 });
  }
}

export async function PUT(req: NextRequest) {
  const unauthorized = checkAuth(req);
  if (unauthorized) return unauthorized;

  let body: unknown;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "请求体不是合法 JSON" }, { status: 400 });
  }

  const result = validateTerminology(body);
  if (!result.ok || !result.value) {
    return NextResponse.json(
      { error: result.error ?? "专有术语库校验失败" },
      { status: 400 }
    );
  }

  try {
    await saveTerminology(result.value);
    return NextResponse.json({ ok: true, count: result.value.length });
  } catch {
    return NextResponse.json({ error: "保存失败" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import * as XLSX from "xlsx";
import { checkAuth } from "@/lib/auth";
import type { UnifiedTerm } from "@/lib/types";

export const runtime = "nodejs";
export const maxDuration = 60;

const MAX_FILE_BYTES = 10 * 1024 * 1024;

function cell(row: unknown[], idx: number): string {
  if (idx < 0) return "";
  const v = row[idx];
  return v == null ? "" : String(v).trim();
}

function findCol(header: string[], match: (h: string) => boolean): number {
  return header.findIndex((h) => match((h ?? "").toString().trim()));
}

function sheetRows(sheet: XLSX.WorkSheet): unknown[][] {
  return XLSX.utils.sheet_to_json<unknown[]>(sheet, {
    header: 1,
    blankrows: false,
    defval: "",
  });
}

// 统一表述类:有「中文 / ZH」列且有「英文 / EN」或「法文 / FR」列
function parseUnified(rows: unknown[][]): UnifiedTerm[] | null {
  if (rows.length < 2) return null;
  const header = (rows[0] as string[]).map((h) => (h ?? "").toString().trim());
  const zhCol = findCol(header, (h) => h === "ZH" || h.includes("中文"));
  const enCol = findCol(header, (h) => h === "EN" || h.includes("英"));
  const frCol = findCol(header, (h) => h === "FR" || h.includes("法"));
  if (zhCol < 0 || (enCol < 0 && frCol < 0)) return null;
  const catCol = findCol(header, (h) => h.includes("分类") || h.includes("类别"));
  const srcCol = findCol(header, (h) => h.includes("来源"));

  const out: UnifiedTerm[] = [];
  for (let i = 1; i < rows.length; i++) {
    const r = rows[i];
    const zh = cell(r, zhCol);
    const en = cell(r, enCol);
    const fr = cell(r, frCol);
    if (!zh && !en && !fr) continue;
    out.push({
      category: cell(r, catCol),
      zh,
      en,
      fr,
      source: cell(r, srcCol) || undefined,
    });
  }
  return out.length > 0 ? out : null;
}

// 上传 xlsx → 解析统一表述术语。确定性解析,不走模型。
export async function POST(req: NextRequest) {
  const unauthorized = checkAuth(req);
  if (unauthorized) return unauthorized;

  let form: FormData;
  try {
    form = await req.formData();
  } catch {
    return NextResponse.json({ error: "上传内容无法解析" }, { status: 400 });
  }

  const file = form.get("file");
  if (!(file instanceof File)) {
    return NextResponse.json({ error: "未找到上传的文件" }, { status: 400 });
  }
  if (file.size > MAX_FILE_BYTES) {
    return NextResponse.json(
      { error: `文件过大(上限 ${Math.floor(MAX_FILE_BYTES / 1024 / 1024)}MB)` },
      { status: 413 }
    );
  }
  if (!/\.xls[xm]?$/i.test(file.name)) {
    return NextResponse.json(
      { error: "请上传 .xlsx / .xls 文件" },
      { status: 415 }
    );
  }

  try {
    const buffer = Buffer.from(await file.arrayBuffer());
    const wb = XLSX.read(buffer, { type: "buffer" });

    const terms: UnifiedTerm[] = [];
    for (const name of wb.SheetNames) {
      const rows = sheetRows(wb.Sheets[name]);
      if (rows.length < 2) continue;
      const u = parseUnified(rows);
      if (u) terms.push(...u);
    }

    if (terms.length === 0) {
      return NextResponse.json(
        { error: "未识别到术语表:请确认表头含 ZH/EN 或 中文/英文 列" },
        { status: 422 }
      );
    }

    return NextResponse.json({
      terms,
      filename: file.name,
    });
  } catch {
    return NextResponse.json(
      { error: "xlsx 解析失败,请确认文件未损坏" },
      { status: 500 }
    );
  }
}

"use client";

import { useEffect, useRef, useState } from "react";
import type { UnifiedTerm } from "@/lib/types";
import { authFetch } from "@/lib/clientAuth";

const inputCls =
  "w-full rounded border border-gray-200 px-2 py-1.5 text-sm focus:border-brand focus:outline-none";

const EMPTY_TERM: UnifiedTerm = { category: "", zh: "", en: "", fr: "", source: "" };

interface Props {
  compact?: boolean;
}

export default function TerminologyManager({ compact = false }: Props) {
  const [terms, setTerms] = useState<UnifiedTerm[] | null>(null);
  const [q, setQ] = useState("");
  const [saving, setSaving] = useState(false);
  const [importing, setImporting] = useState(false);
  const [msg, setMsg] = useState("");
  const fileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    fetch("/api/terminology")
      .then((r) => (r.ok ? r.json() : []))
      .then((d) => setTerms(Array.isArray(d) ? d : []))
      .catch(() => setTerms([]));
  }, []);

  function update(idx: number, patch: Partial<UnifiedTerm>) {
    setTerms((p) =>
      p ? p.map((r, i) => (i === idx ? { ...r, ...patch } : r)) : p
    );
  }

  async function onImport(file: File) {
    setImporting(true);
    setMsg(`正在解析 ${file.name} …`);
    try {
      const form = new FormData();
      form.append("file", file);
      const res = await authFetch("/api/terminology/import", {
        method: "POST",
        body: form,
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) {
        setMsg(`导入失败:${data.error || res.status}`);
        return;
      }
      const added: UnifiedTerm[] = Array.isArray(data.terms) ? data.terms : [];
      setTerms((p) => [...(p ?? []), ...added]);
      setMsg(`已导入 +${added.length} 条术语,核对后点保存`);
    } catch {
      setMsg("导入请求失败");
    } finally {
      setImporting(false);
    }
  }

  async function save() {
    if (!terms) return;
    setSaving(true);
    setMsg("");
    try {
      const res = await authFetch("/api/terminology", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(terms),
      });
      const data = await res.json().catch(() => ({}));
      setMsg(
        res.ok
          ? `已保存 ${data.count} 条术语`
          : `保存失败:${data.error || res.status}`
      );
    } catch {
      setMsg("保存请求失败");
    } finally {
      setSaving(false);
    }
  }

  if (!terms) return <p className="text-sm text-ink-faint">加载中…</p>;

  const kw = q.trim().toLowerCase();
  const filtered = terms
    .map((r, i) => ({ r, i }))
    .filter(
      ({ r }) =>
        !kw ||
        [r.category, r.zh, r.en, r.fr, r.source ?? ""]
          .join(" ")
          .toLowerCase()
          .includes(kw)
    );

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap items-center gap-2">
        <span className="text-sm text-ink-soft">{terms.length} 条</span>

        <input
          value={q}
          onChange={(e) => setQ(e.target.value)}
          placeholder="搜索术语…"
          className="min-w-[160px] flex-1 rounded border border-gray-200 px-2 py-1.5 text-sm focus:border-brand focus:outline-none"
        />

        <input
          ref={fileRef}
          type="file"
          accept=".xlsx,.xls"
          className="hidden"
          onChange={(e) => {
            const f = e.target.files?.[0];
            if (f) onImport(f);
            e.target.value = "";
          }}
        />
        <button
          type="button"
          disabled={importing}
          onClick={() => fileRef.current?.click()}
          className="rounded-lg border border-gray-200 bg-white px-3 py-1.5 text-sm text-ink-soft hover:border-brand disabled:opacity-60"
          title="上传 xlsx,按表头自动解析"
        >
          {importing ? "导入中…" : "上传 xlsx"}
        </button>
        <button
          type="button"
          onClick={save}
          disabled={saving || importing}
          className="rounded-lg bg-brand px-4 py-1.5 text-sm font-semibold text-white hover:bg-brand-dark disabled:opacity-60"
        >
          {saving ? "保存中…" : "保存术语库"}
        </button>
        {msg && <span className="text-xs text-ink-soft">{msg}</span>}
      </div>

      <p className="text-xs text-ink-faint">
        中/英/法三语对照,润色时自动匹配原文命中的术语,作为拼写/表达软参考注入,不强制改写其它内容。
      </p>

      <div className={"space-y-2 " + (compact ? "max-h-[360px] overflow-auto pr-1" : "")}>
        {filtered.map(({ r, i }) => (
          <div
            key={i}
            className="grid grid-cols-1 gap-2 md:grid-cols-[1fr_1.2fr_1.2fr_1.2fr_1fr_auto]"
          >
            <input value={r.category} onChange={(e) => update(i, { category: e.target.value })} placeholder="分类" className={inputCls} />
            <input value={r.zh} onChange={(e) => update(i, { zh: e.target.value })} placeholder="中文 ZH" className={inputCls} />
            <input value={r.en} onChange={(e) => update(i, { en: e.target.value })} placeholder="英文 EN" className={inputCls} />
            <input value={r.fr} onChange={(e) => update(i, { fr: e.target.value })} placeholder="法文 FR" className={inputCls} />
            <input value={r.source ?? ""} onChange={(e) => update(i, { source: e.target.value })} placeholder="来源" className={inputCls} />
            <button
              type="button"
              onClick={() => setTerms((p) => p ? p.filter((_, j) => j !== i) : p)}
              className="text-sm text-red-600 hover:underline"
            >
              删
            </button>
          </div>
        ))}
        <button
          type="button"
          onClick={() => setTerms((p) => (p ? [...p, { ...EMPTY_TERM }] : p))}
          className="text-xs text-brand-dark hover:underline"
        >
          + 添加术语
        </button>
      </div>
    </div>
  );
}
